select case when age >= 58 then 'HIGH' else 'LOW' end as age_tier, date_trunc('quarter', signup_date) as quarter_start, corr(age, credit_limit) as corr_age_credit_limit, avg(credit_limit) filter (where city = 'Berlin') as berlin_avg_credit_limit, round(sum(credit_limit) / nullif(count(case when city = 'Bangkok' then 1 end), 0), 2) as credit_limit_per_bangkok, sum(credit_limit) as total_credit_limit, corr(age, credit_limit) as corr_age_credit_limit_2, sum(case when city = 'London' then age else 0 end) as london_age from customers group by age_tier, quarter_start;
